<script setup lang="ts">
import { registrationEnabled } from '@/app/siteMode'
import { reactive, ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage } from '@/app/messages';import { login } from '@/api/user';import { readableError } from '@/api/errors';import { queryClient } from '@/app/state';import { sessionKey } from '@/composables/useSession';import { safeReturnTo } from '@/app/router'
const route=useRoute(),router=useRouter(),busy=ref(false),error=ref('');const form=reactive({userAccount:'',userPassword:''})
async function submit(){error.value='';if(form.userAccount.length<4){error.value='账号至少 4 位';return}if(form.userPassword.length<8){error.value='密码至少 8 位';return}busy.value=true;try{const user=await login({...form});queryClient.setQueryData(sessionKey,user);ElMessage.success({ message: '登录成功' });await router.replace(user.userRole==='admin'?'/admin/problems':safeReturnTo(route.query.returnTo))}catch(e){error.value=readableError(e)}finally{busy.value=false}}
</script>
<template><section><h1>登录 NemoOJ</h1><p class="hint">继续完成你的编程练习</p><el-form label-position="top" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="form.userAccount" autocomplete="username" maxlength="256" @keyup.enter="submit"/></el-form-item><el-form-item label="密码"><el-input v-model="form.userPassword" type="password" autocomplete="current-password" show-password @keyup.enter="submit"/></el-form-item><p v-if="error" class="form-error" role="alert">{{error}}</p><el-button class="submit" type="primary" :loading="busy" @click="submit">登录</el-button></el-form><p v-if="registrationEnabled" class="switch">还没有账号？<RouterLink to="/register">立即注册</RouterLink></p><p v-else class="switch">注册暂未开放，请使用已有账号登录</p></section></template>
<style scoped>h1{font-size:24px;margin:0}.hint{color:var(--oj-text-muted);margin:8px 0 26px}.submit{width:100%;height:40px}.form-error{color:var(--oj-danger);margin:-4px 0 14px}.switch{text-align:center;color:var(--oj-text-muted);margin:22px 0 0}</style>
